// Phase 1: Integration Tests
// Parser + Editor + Executor 통합 테스트

// ============================================================================
// Test 1: End-to-End: Parse → Edit → Execute
// ============================================================================

test "integration_parse_edit_execute" {
    // Step 1: .flmd 파일 파싱
    let content = "# Calculator\n\nSimple calculator example.\n\n```fvlang\nfn add(a: i32, b: i32) -> i32 {\n    a + b\n}\n```"
    let doc_result = parse_flmd(content)
    assert(doc_result.is_ok())

    // Step 2: 에디터에 로드
    let mut editor = create_editor(800, 600)
    let load_result = editor.load_document(content)
    assert(load_result.is_ok())
    assert(editor.state.document.title == "Calculator")

    // Step 3: 코드 블록 선택 및 수정
    editor.select_block(0)
    let code = editor.get_selected_code()
    assert(code.is_some())
}

// ============================================================================
// Test 2: Parser produces valid AST
// ============================================================================

test "integration_parser_ast_validity" {
    let content = "# Test\n\n## Section\n\nContent\n\n```fvlang\nfn main() { }\n```"
    let doc = parse_flmd(content).unwrap()

    assert(doc.title == "Test")
    assert(doc.blocks.len() > 0)
    assert(!doc.metadata.version.is_empty())
}

// ============================================================================
// Test 3: Editor can render HTML
// ============================================================================

test "integration_editor_html_rendering" {
    let mut editor = create_editor(1024, 768)

    let content = "# Sovereign Workspace\n\nTest content"
    editor.load_document(content).unwrap()

    let html = editor.render_html()
    assert(html.contains("<!DOCTYPE html>"))
    assert(html.contains("Sovereign Workspace"))
    assert(html.contains("<div class=\"container\">"))
}

// ============================================================================
// Test 4: Code block extraction
// ============================================================================

test "integration_code_block_extraction" {
    let content = "# Test\n\n```fvlang\nfn test() {\n    print(\"test\")\n}\n```"
    let doc = parse_flmd(content).unwrap()

    assert(doc.blocks.len() > 0)

    let mut found_code = false
    for block in doc.blocks {
        match block {
            BlockType::CodeBlock(code) => {
                assert(code.contains("fn test()"))
                found_code = true
            }
            _ => {}
        }
    }
    assert(found_code)
}

// ============================================================================
// Test 5: Multiple code blocks
// ============================================================================

test "integration_multiple_code_blocks" {
    let content = "# Multi-Code\n\n```fvlang\nfn a() { }\n```\n\n```fvlang\nfn b() { }\n```"
    let doc = parse_flmd(content).unwrap()

    let code_blocks: Vec<_> = doc.blocks.iter()
        .filter(|b| matches!(b, BlockType::CodeBlock(_)))
        .collect()

    assert(code_blocks.len() >= 1)
}

